<?php foreach(['close'=>['Clôturer cette recette ?','La recette ne pourra plus être modifiée ni supprimée.','Clôturer'],'delete'=>['Supprimer cette recette ?','Cette action est irréversible.','Supprimer']] as $type=>$copy):?><div class="users-modal-overlay" id="<?= $type ?>-income-modal"><div class="users-modal confirm-modal"><span class="warning-icon"><i class="bi bi-<?= $type==='close'?'lock':'exclamation-triangle' ?>"></i></span><h3><?= $copy[0] ?></h3><p><strong id="<?= $type ?>-income-name"></strong><br><?= $copy[1] ?></p><form method="POST" action="<?= BASE_URL ?>/recettes"><input type="hidden" name="action" value="<?= $type ?>"><input type="hidden" name="id" id="<?= $type ?>-income-id"><div class="modal-buttons"><button type="button" class="cancel" onclick="closeModal('<?= $type ?>-income-modal')">Annuler</button><button class="<?= $type==='delete'?'delete-confirm':'save' ?>"><?= $copy[2] ?></button></div></form></div></div><?php endforeach;?>
<link href="<?= BASE_URL ?>/assets/css/searchable-select.css" rel="stylesheet">
<script>
function openIncomeModal(r=null){document.getElementById('income-action').value=r?'update':'create';document.getElementById('income-id').value=r?.id||'';document.getElementById('affection_vehicule').value=r?.affection_vehicule||'';document.getElementById('date_recette').value=r?.date_recette||'<?= date('Y-m-d') ?>';document.getElementById('montant').value=r?.montant||'';document.getElementById('devise').value=r?.devise||'USD';document.getElementById('description').value=r?.description||'';document.getElementById('currency-label').textContent=r?.devise||'USD';document.getElementById('income-title').textContent=r?'Modifier la recette':'Nouvelle recette';openModal('income-modal')}document.getElementById('devise').onchange=e=>document.getElementById('currency-label').textContent=e.target.value;function filterIncomes(){const q=document.getElementById('income-search').value.toLowerCase().trim(),c=document.getElementById('income-currency').value,s=document.getElementById('income-state').value;let n=0;document.querySelectorAll('#incomes-body tr[data-search]').forEach(r=>{const show=(!q||r.dataset.search.includes(q))&&(!c||r.dataset.currency===c)&&(!s||r.dataset.state===s);r.style.display=show?'':'none';if(show)n++});document.getElementById('income-count').textContent=n+' recette(s)'}function openCloseIncome(id,n){document.getElementById('close-income-id').value=id;document.getElementById('close-income-name').textContent=n;openModal('close-income-modal')}function openDeleteIncome(id,n){document.getElementById('delete-income-id').value=id;document.getElementById('delete-income-name').textContent=n;openModal('delete-income-modal')}function openModal(id){document.getElementById(id).classList.add('show')}function closeModal(id){document.getElementById(id).classList.remove('show')}function toggleSidebar(){document.getElementById('dashboard-sidebar').classList.toggle('open');document.getElementById('mobile-overlay').classList.toggle('show')}setTimeout(()=>document.querySelector('.users-toast')?.remove(),4000);
function openIncomeModal(r=null){document.getElementById('income-action').value=r?'update':'create';document.getElementById('income-id').value=r?.id||'';const assignmentSelect=document.getElementById('affection_vehicule');if(r&&!Array.from(assignmentSelect.options).some(o=>String(o.value)===String(r.affection_vehicule)))assignmentSelect.add(new Option(`${r.immatriculation} — ${r.nom} ${r.postnom||''} ${r.prenom||''}`,r.affection_vehicule));assignmentSelect.value=r?.affection_vehicule||'';document.getElementById('date_recette').value=r?.date_recette||'<?= date('Y-m-d') ?>';document.getElementById('montant').value=r?.montant||'';document.getElementById('devise').value=r?.devise||'USD';document.getElementById('description').value=r?.description||'';document.getElementById('currency-label').textContent=r?.devise||'USD';document.getElementById('income-title').textContent=r?'Modifier la recette':'Nouvelle recette';openModal('income-modal')}
function setupAssignmentSearch(){const select=document.getElementById('affection_vehicule');let box=document.getElementById('assignment-searchable');if(!box){box=document.createElement('div');box.id='assignment-searchable';box.className='searchable-select';box.innerHTML='<input type="search" class="searchable-select-input" id="assignment-search-input" placeholder="Nom ou matricule du chauffeur…" autocomplete="off"><i class="bi bi-search searchable-select-icon"></i><div class="searchable-select-results hidden" id="assignment-search-results"></div>';select.parentNode.insertBefore(box,select);select.classList.add('native-search-select');const input=box.querySelector('input');input.addEventListener('input',()=>renderAssignmentResults(input.value));input.addEventListener('focus',()=>renderAssignmentResults(input.value))}const selected=select.options[select.selectedIndex];document.getElementById('assignment-search-input').value=select.value&&selected?selected.text.trim():'';document.getElementById('assignment-search-results').classList.add('hidden')}
function renderAssignmentResults(query=''){const select=document.getElementById('affection_vehicule'),results=document.getElementById('assignment-search-results'),term=query.toLowerCase().trim();const options=Array.from(select.options).filter(o=>o.value&&(!term||o.text.toLowerCase().includes(term)));results.innerHTML=options.length?options.map(o=>`<button type="button" class="searchable-option ${o.value===select.value?'selected':''}" data-id="${o.value}"><i class="bi bi-person-vcard"></i><span><strong>${escapeIncomeHtml(o.text.split('—')[1]?.trim()||o.text.trim())}</strong><small>${escapeIncomeHtml(o.text.split('—')[0]?.trim()||'Affectation')}</small></span></button>`).join(''):'<div class="searchable-empty">Aucun chauffeur trouvé.</div>';results.classList.remove('hidden');results.querySelectorAll('.searchable-option').forEach(button=>button.onclick=()=>selectAssignmentOption(button.dataset.id))}
function selectAssignmentOption(id){const select=document.getElementById('affection_vehicule');select.value=id;document.getElementById('assignment-search-input').value=select.options[select.selectedIndex].text.trim();document.getElementById('assignment-search-results').classList.add('hidden')}
function escapeIncomeHtml(value){const element=document.createElement('div');element.textContent=value||'';return element.innerHTML}
const assignmentDriverData=<?= json_encode($affectations, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES) ?>;
function enrichAssignmentOptions(current=null){const select=document.getElementById('affection_vehicule');Array.from(select.options).forEach(option=>{if(!option.value)return;const row=assignmentDriverData.find(a=>String(a.id)===String(option.value));if(row&&!option.text.includes(row.matricule))option.text=`${row.immatriculation} — ${[row.nom,row.postnom,row.prenom].filter(Boolean).join(' ')} [${row.matricule}] (${row.fonction_nom})`});if(current){const option=Array.from(select.options).find(o=>String(o.value)===String(current.affection_vehicule));if(option&&current.travailleur_matricule&&!option.text.includes(current.travailleur_matricule))option.text=`${current.immatriculation} — ${[current.nom,current.postnom,current.prenom].filter(Boolean).join(' ')} [${current.travailleur_matricule}] (${current.fonction_nom})`}}
const openIncomeModalWithSelect=openIncomeModal;openIncomeModal=function(r=null){openIncomeModalWithSelect(r);enrichAssignmentOptions(r);setupAssignmentSearch()};
</script></body></html>
